// Approach 1: Extending Thread (less preferred)
class DownloadThread extends Thread {
    private final String url;

    DownloadThread(String url) {
        this.url = url;
    }

    @Override
    public void run() {
        System.out.println("Downloading from " + url);
        // Download logic here
    }
}

// Approach 2: Implementing Runnable (preferred)
class DownloadTask implements Runnable {
    private final String url;

    DownloadTask(String url) {
        this.url = url;
    }

    @Override
    public void run() {
        System.out.println("Downloading from " + url);
        // Download logic here
    }
}

// Usage comparison
var thread1 = new DownloadThread("https://api.example.com/data");
thread1.start();  // Extends Thread, call start() directly

var task = new DownloadTask("https://api.example.com/data");
var thread2 = new Thread(task);  // Runnable needs Thread wrapper
thread2.start();
