class DataProcessor implements Runnable {
    private final String taskName;

    DataProcessor(String taskName) {
        this.taskName = taskName;
    }

    @Override
    public void run() {
        System.out.println(taskName + " running on: " + 
            Thread.currentThread().getName());
        // Simulate processing
        for (int i = 1; i <= 3; i++) {
            System.out.println(taskName + " - step " + i);
        }
    }
}

var task1 = new DataProcessor("Task1");
var task2 = new DataProcessor("Task2");

var thread1 = new Thread(task1);
var thread2 = new Thread(task2);

thread1.run();   // BAD: runs in main thread, blocks until done
thread2.run();   // BAD: runs in main thread after task1 finishes

thread1.start(); // GOOD: creates new thread, runs concurrently
thread2.start(); // GOOD: creates another thread, both run in parallel

// Output with run(): Task1 and Task2 run sequentially on main thread
// Output with start(): Task1 and Task2 interleave on separate threads
