import java.util.concurrent.*;
import java.util.*;

record Order(Long id, String customer, double total) {}

class OrderPriceCalculator implements Callable<Double> {
    private final Long orderId;

    OrderPriceCalculator(Long orderId) {
        this.orderId = orderId;
    }

    @Override
    public Double call() throws Exception {
        // Simulate database call that might throw SQLException
        Thread.sleep(100);  // Simulate I/O delay
        return orderId * 10.0;  // Return calculated price
    }
}

var executor = Executors.newFixedThreadPool(3);

// Submit multiple Callable tasks
var future1 = executor.submit(new OrderPriceCalculator(101L));
var future2 = executor.submit(new OrderPriceCalculator(102L));

try {
    var price1 = future1.get();  // Blocks until result ready
    var price2 = future2.get(5, TimeUnit.SECONDS);  // Timeout protection
    System.out.println("Total: " + (price1 + price2));
} catch (ExecutionException e) {
    System.err.println("Task failed: " + e.getCause());  // Unwrap exception
} finally {
    executor.shutdown();
}
