import java.util.concurrent.*;
import java.util.*;

// BAD: Creating threads directly (don't do this)
class OrderService {
    void processOrders(List<Order> orders) {
        for (var order : orders) {
            new Thread(() -> processOrder(order)).start();  // Creates 1000 threads for 1000 orders!
        }
    }

    void processOrder(Order order) {
        System.out.println("Processing: " + order);
    }
}

// GOOD: Using ExecutorService with thread pool
class ImprovedOrderService {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);

    void processOrders(List<Order> orders) {
        for (var order : orders) {
            executor.submit(() -> processOrder(order));  // Reuses 10 threads
        }
    }

    void processOrder(Order order) {
        System.out.println("Processing: " + order);
    }

    void shutdown() {
        executor.shutdown();  // Graceful shutdown
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();  // Force shutdown if timeout
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}

record Order(Long id, String product) {}
