import java.time.*;

class HealthCheckMonitor implements Runnable {
    @Override
    public void run() {
        while (true) {  // Infinite loop is OK for daemon thread
            System.out.println("[" + LocalTime.now() + "] Health check: System OK");
            try {
                Thread.sleep(5000);  // Check every 5 seconds
            } catch (InterruptedException e) {
                System.out.println("Health monitor interrupted");
                return;
            }
        }
    }
}

class Application {
    public static void main(String[] args) throws InterruptedException {
        var healthMonitor = new Thread(new HealthCheckMonitor());
        healthMonitor.setDaemon(true);  // MUST be before start()
        healthMonitor.start();

        // Main business logic
        System.out.println("Application started");
        Thread.sleep(12000);  // Run for 12 seconds
        System.out.println("Application finishing");

        // When main thread exits, daemon thread is killed automatically
        // No need to explicitly stop the health monitor
    }
}

// Output: Health checks run every 5 seconds, stop when main exits
